CREATE OR REPLACE FUNCTION public.consume_credits_once(p_user_id uuid, p_amount integer, p_resource_type text, p_resource_id uuid, p_description text, p_operation_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_existing_transaction record;
  v_user_balance integer;
  v_remaining integer := p_amount;
  v_new_balance integer;
  v_source record;
  v_deduct integer;
  v_consumptions jsonb := '[]'::jsonb;
  v_transaction_id uuid;
begin
  if auth.uid() is distinct from p_user_id and not coalesce(public.is_admin(), false) then
    raise exception '권한이 없습니다.';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception '차감할 크레딧은 0보다 커야 합니다.';
  end if;

  if p_operation_key is null or length(trim(p_operation_key)) = 0 then
    raise exception 'operation_key가 필요합니다.';
  end if;

  select id, balance_after
    into v_existing_transaction
    from public.credit_transactions
    where user_id = p_user_id
      and operation_key = p_operation_key
      and type = 'consume'
    limit 1;

  if found then
    select coalesce(
      jsonb_agg(jsonb_build_object('source_id', source_id, 'amount', amount, 'transaction_id', transaction_id)),
      '[]'::jsonb
    )
      into v_consumptions
      from public.credit_consumption
      where transaction_id = v_existing_transaction.id;

    return jsonb_build_object(
      'new_balance', v_existing_transaction.balance_after,
      'transaction_id', v_existing_transaction.id,
      'consumptions', v_consumptions,
      'idempotent', true
    );
  end if;

  select credits
    into v_user_balance
    from public.profiles
    where id = p_user_id
    for update;

  if v_user_balance is null then
    raise exception '사용자 정보를 찾을 수 없습니다.';
  end if;

  if v_user_balance < p_amount then
    raise exception '크레딧이 부족합니다.';
  end if;

  v_new_balance := v_user_balance - p_amount;

  insert into public.credit_transactions (
    user_id,
    type,
    amount,
    balance_after,
    description,
    resource_type,
    resource_id,
    operation_key
  ) values (
    p_user_id,
    'consume',
    -p_amount,
    v_new_balance,
    p_description,
    p_resource_type,
    p_resource_id,
    p_operation_key
  ) returning id into v_transaction_id;

  for v_source in
    select id, remaining_credits
      from public.credit_sources
      where user_id = p_user_id
        and status = 'active'
        and remaining_credits > 0
      order by purchased_at asc
      for update
  loop
    exit when v_remaining <= 0;

    v_deduct := least(v_source.remaining_credits, v_remaining);

    update public.credit_sources
      set remaining_credits = remaining_credits - v_deduct
      where id = v_source.id;

    insert into public.credit_consumption (
      user_id,
      source_id,
      amount,
      resource_type,
      resource_id,
      description,
      transaction_id,
      operation_key
    ) values (
      p_user_id,
      v_source.id,
      v_deduct,
      p_resource_type,
      p_resource_id,
      p_description,
      v_transaction_id,
      p_operation_key
    );

    v_consumptions := v_consumptions || jsonb_build_array(jsonb_build_object(
      'source_id', v_source.id,
      'amount', v_deduct,
      'transaction_id', v_transaction_id
    ));

    v_remaining := v_remaining - v_deduct;
  end loop;

  if v_remaining > 0 then
    raise exception '크레딧이 부족합니다.';
  end if;

  update public.profiles
    set credits = v_new_balance
    where id = p_user_id;

  return jsonb_build_object(
    'new_balance', v_new_balance,
    'transaction_id', v_transaction_id,
    'consumptions', v_consumptions,
    'idempotent', false
  );
exception when unique_violation then
  select id, balance_after
    into v_existing_transaction
    from public.credit_transactions
    where user_id = p_user_id
      and operation_key = p_operation_key
      and type = 'consume'
    limit 1;

  if not found then
    raise;
  end if;

  select coalesce(
    jsonb_agg(jsonb_build_object('source_id', source_id, 'amount', amount, 'transaction_id', transaction_id)),
    '[]'::jsonb
  )
    into v_consumptions
    from public.credit_consumption
    where transaction_id = v_existing_transaction.id;

  return jsonb_build_object(
    'new_balance', v_existing_transaction.balance_after,
    'transaction_id', v_existing_transaction.id,
    'consumptions', v_consumptions,
    'idempotent', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.refund_credits_once(p_user_id uuid, p_amount integer, p_resource_type text, p_resource_id uuid, p_description text, p_operation_key text, p_original_operation_key text, p_target_balance integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_existing_transaction record;
  v_original_transaction record;
  v_current_balance integer;
  v_new_balance integer;
  v_consumption record;
  v_total_refunded integer := 0;
  v_remaining_refund integer := p_amount;
  v_source_initial integer;
  v_refund_amount integer;
  v_transaction_id uuid;
begin
  if auth.uid() is distinct from p_user_id
    and coalesce(auth.role(), '') <> 'service_role'
    and not coalesce(public.is_admin(), false) then
    raise exception '권한이 없습니다.';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception '환불할 크레딧은 0보다 커야 합니다.';
  end if;

  if p_operation_key is null or length(trim(p_operation_key)) = 0 then
    raise exception 'operation_key가 필요합니다.';
  end if;

  if p_original_operation_key is null or length(trim(p_original_operation_key)) = 0 then
    raise exception 'original_operation_key가 필요합니다.';
  end if;

  select id, balance_after
    into v_existing_transaction
    from public.credit_transactions
    where user_id = p_user_id
      and type = 'refund'
      and (
        operation_key = p_operation_key
        or original_operation_key = p_original_operation_key
      )
    limit 1;

  if found then
    return jsonb_build_object(
      'new_balance', v_existing_transaction.balance_after,
      'transaction_id', v_existing_transaction.id,
      'refunded', 0,
      'idempotent', true
    );
  end if;

  select id
    into v_original_transaction
    from public.credit_transactions
    where user_id = p_user_id
      and type = 'consume'
      and operation_key = p_original_operation_key
    limit 1;

  if not found then
    raise exception '원본 차감 거래를 찾을 수 없습니다.';
  end if;

  select credits
    into v_current_balance
    from public.profiles
    where id = p_user_id
    for update;

  if not found then
    raise exception '사용자 정보를 찾을 수 없습니다.';
  end if;

  for v_consumption in
    select source_id, amount
    from public.credit_consumption
    where transaction_id = v_original_transaction.id
    order by created_at desc
  loop
    exit when v_remaining_refund <= 0;

    select initial_credits
      into v_source_initial
      from public.credit_sources
      where id = v_consumption.source_id
      for update;

    v_refund_amount := least(v_consumption.amount, v_remaining_refund);

    update public.credit_sources
      set remaining_credits = least(coalesce(remaining_credits, 0) + v_refund_amount, v_source_initial),
          updated_at = now()
      where id = v_consumption.source_id;

    v_total_refunded := v_total_refunded + v_refund_amount;
    v_remaining_refund := v_remaining_refund - v_refund_amount;
  end loop;

  if v_total_refunded <= 0 then
    raise exception '환불 가능한 소비 내역이 없습니다.';
  end if;

  v_new_balance := coalesce(p_target_balance, v_current_balance + v_total_refunded);

  insert into public.credit_transactions (
    user_id,
    type,
    amount,
    balance_after,
    resource_type,
    resource_id,
    description,
    operation_key,
    original_operation_key
  ) values (
    p_user_id,
    'refund',
    v_total_refunded,
    v_new_balance,
    p_resource_type,
    p_resource_id,
    p_description,
    p_operation_key,
    p_original_operation_key
  ) returning id into v_transaction_id;

  update public.profiles
    set credits = v_new_balance
    where id = p_user_id;

  return jsonb_build_object(
    'new_balance', v_new_balance,
    'transaction_id', v_transaction_id,
    'refunded', v_total_refunded,
    'idempotent', false
  );
exception when unique_violation then
  select id, balance_after
    into v_existing_transaction
    from public.credit_transactions
    where user_id = p_user_id
      and type = 'refund'
      and (
        operation_key = p_operation_key
        or original_operation_key = p_original_operation_key
      )
    limit 1;

  if not found then
    raise;
  end if;

  return jsonb_build_object(
    'new_balance', v_existing_transaction.balance_after,
    'transaction_id', v_existing_transaction.id,
    'refunded', 0,
    'idempotent', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_credits(p_user_id uuid, p_amount integer, p_description text, p_type text DEFAULT 'admin_grant'::text, p_resource_type text DEFAULT NULL::text, p_resource_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  current_balance INTEGER;
  new_balance INTEGER;
BEGIN
  -- Upsert user_credits to ensure it exists
  INSERT INTO public.user_credits (user_id, balance)
  VALUES (p_user_id, 0)
  ON CONFLICT (user_id) DO NOTHING;

  -- Lock row
  SELECT balance INTO current_balance
  FROM public.user_credits
  WHERE user_id = p_user_id
  FOR UPDATE;

  new_balance := current_balance + p_amount;

  -- Update balance
  UPDATE public.user_credits
  SET balance = new_balance, updated_at = NOW()
  WHERE user_id = p_user_id;

  -- Log transaction
  INSERT INTO public.credit_transactions (user_id, amount, type, description, resource_type, resource_id)
  VALUES (p_user_id, p_amount, p_type, p_description, p_resource_type, p_resource_id);

  RETURN new_balance;
END;
$function$

CREATE OR REPLACE FUNCTION public.deduct_credits(p_user_id uuid, p_amount integer, p_description text, p_resource_type text DEFAULT NULL::text, p_resource_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  current_balance INTEGER;
  new_balance INTEGER;
BEGIN
  -- Row Locking for concurrency control
  SELECT balance INTO current_balance
  FROM public.user_credits
  WHERE user_id = p_user_id
  FOR UPDATE;

  -- If user wallet doesn't exist, try to create it (self-healing)
  IF current_balance IS NULL THEN
      INSERT INTO public.user_credits (user_id, balance) VALUES (p_user_id, 0)
      ON CONFLICT DO NOTHING;
      -- Return -1 if insufficient (0 < amount) generally, or re-select. 
      -- Simple restart for safety:
      SELECT balance INTO current_balance FROM public.user_credits WHERE user_id = p_user_id;
  END IF;

  IF current_balance >= p_amount THEN
    new_balance := current_balance - p_amount;

    -- Update balance
    UPDATE public.user_credits
    SET balance = new_balance, updated_at = NOW()
    WHERE user_id = p_user_id;

    -- Insert transaction log
    INSERT INTO public.credit_transactions (user_id, amount, type, description, resource_type, resource_id)
    VALUES (p_user_id, -p_amount, 'use', p_description, p_resource_type, p_resource_id);

    RETURN new_balance;
  ELSE
    RETURN -1; -- Insufficient funds
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_credits(p_user_id uuid, p_amount integer, p_resource_type text, p_resource_id uuid, p_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_available integer := 0;
  v_remaining integer := p_amount;
  v_new_balance integer := 0;
  v_source RECORD;
  v_deduct integer;
  v_consumptions jsonb := '[]'::jsonb;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'INVALID_CREDIT_AMOUNT';
  END IF;

  PERFORM 1
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CREDIT_USER_NOT_FOUND';
  END IF;

  PERFORM 1
    FROM public.credit_sources
   WHERE user_id = p_user_id
     AND status = 'active'
     AND remaining_credits > 0
     AND (expires_at IS NULL OR expires_at > now())
   ORDER BY expires_at ASC NULLS LAST, purchased_at ASC, id ASC
   FOR UPDATE;

  SELECT COALESCE(SUM(remaining_credits), 0)::integer
    INTO v_available
    FROM public.credit_sources
   WHERE user_id = p_user_id
     AND status = 'active'
     AND remaining_credits > 0
     AND (expires_at IS NULL OR expires_at > v_now);

  IF v_available < p_amount THEN
    RAISE EXCEPTION 'INSUFFICIENT_CREDITS';
  END IF;

  FOR v_source IN
    SELECT id, remaining_credits
      FROM public.credit_sources
     WHERE user_id = p_user_id
       AND status = 'active'
       AND remaining_credits > 0
       AND (expires_at IS NULL OR expires_at > now())
     ORDER BY expires_at ASC NULLS LAST, purchased_at ASC, id ASC
     FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;

    v_deduct := LEAST(v_source.remaining_credits, v_remaining);

    UPDATE public.credit_sources
       SET remaining_credits = remaining_credits - v_deduct
     WHERE id = v_source.id;

    INSERT INTO public.credit_consumption (
      user_id,
      source_id,
      amount,
      resource_type,
      resource_id,
      description
    ) VALUES (
      p_user_id,
      v_source.id,
      v_deduct,
      p_resource_type,
      p_resource_id,
      p_description
    );

    v_consumptions := v_consumptions || jsonb_build_array(
      jsonb_build_object('source_id', v_source.id, 'amount', v_deduct)
    );
    v_remaining := v_remaining - v_deduct;
  END LOOP;

  SELECT COALESCE(SUM(remaining_credits), 0)::integer
    INTO v_new_balance
    FROM public.credit_sources
   WHERE user_id = p_user_id
     AND status IN ('active', 'pending_refund')
     AND (expires_at IS NULL OR expires_at > v_now);

  UPDATE public.profiles
     SET credits = v_new_balance
   WHERE id = p_user_id;

  INSERT INTO public.credit_transactions (
    user_id,
    type,
    amount,
    balance_after,
    description,
    resource_type,
    resource_id
  ) VALUES (
    p_user_id,
    'consume',
    -p_amount,
    v_new_balance,
    p_description,
    p_resource_type,
    p_resource_id
  );

  RETURN jsonb_build_object(
    'new_balance', v_new_balance,
    'consumptions', v_consumptions
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_credits(p_user_id uuid, p_amount integer, p_resource_type text, p_resource_id uuid, p_description text, p_consumptions jsonb, p_target_balance integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_item jsonb;
  v_source_id uuid;
  v_refund_amount integer;
  v_remaining_refund integer := p_amount;
  v_total_refunded integer := 0;
  v_source_initial integer;
  v_new_balance integer;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'INVALID_CREDIT_REFUND_AMOUNT';
  END IF;

  IF p_consumptions IS NULL
     OR jsonb_typeof(p_consumptions) <> 'array'
     OR jsonb_array_length(p_consumptions) = 0 THEN
    RAISE EXCEPTION 'CREDIT_REFUND_SOURCE_REQUIRED';
  END IF;

  PERFORM 1
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CREDIT_USER_NOT_FOUND';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_consumptions)
  LOOP
    EXIT WHEN v_remaining_refund <= 0;

    v_source_id := NULLIF(v_item->>'source_id', '')::uuid;
    v_refund_amount := COALESCE((v_item->>'amount')::integer, 0);

    IF v_source_id IS NULL OR v_refund_amount <= 0 THEN
      CONTINUE;
    END IF;

    SELECT initial_credits
      INTO v_source_initial
      FROM public.credit_sources
     WHERE id = v_source_id
       AND user_id = p_user_id
     FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CREDIT_REFUND_SOURCE_NOT_FOUND';
    END IF;

    v_refund_amount := LEAST(v_refund_amount, v_remaining_refund);

    UPDATE public.credit_sources
       SET remaining_credits = LEAST(
         remaining_credits + v_refund_amount,
         v_source_initial
       )
     WHERE id = v_source_id;

    v_total_refunded := v_total_refunded + v_refund_amount;
    v_remaining_refund := v_remaining_refund - v_refund_amount;
  END LOOP;

  SELECT COALESCE(SUM(remaining_credits), 0)::integer
    INTO v_new_balance
    FROM public.credit_sources
   WHERE user_id = p_user_id
     AND status IN ('active', 'pending_refund')
     AND (expires_at IS NULL OR expires_at > v_now);

  IF p_target_balance IS NOT NULL THEN
    v_new_balance := LEAST(v_new_balance, p_target_balance);
  END IF;

  UPDATE public.profiles
     SET credits = v_new_balance
   WHERE id = p_user_id;

  INSERT INTO public.credit_transactions (
    user_id,
    type,
    amount,
    balance_after,
    description,
    resource_type,
    resource_id
  ) VALUES (
    p_user_id,
    'refund',
    v_total_refunded,
    v_new_balance,
    p_description,
    p_resource_type,
    p_resource_id
  );

  RETURN jsonb_build_object(
    'new_balance', v_new_balance,
    'refunded', v_total_refunded
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_point_charge_refund_eligibility(p_user_id uuid, p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_source public.credit_sources%ROWTYPE;
  v_order public.payment_orders%ROWTYPE;
  v_refundable_until timestamptz;
BEGIN
  SELECT * INTO v_source
    FROM public.credit_sources
   WHERE id = p_source_id
     AND user_id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason_code', 'REFUND_SOURCE_NOT_FOUND');
  END IF;

  IF v_source.payment_order_id IS NULL
     OR v_source.source_category <> 'plan_purchase' THEN
    RETURN jsonb_build_object('allowed', false, 'reason_code', 'REFUND_PAID_SOURCE_REQUIRED');
  END IF;

  SELECT * INTO v_order
    FROM public.payment_orders
   WHERE id = v_source.payment_order_id
     AND user_id = p_user_id;

  IF NOT FOUND
     OR v_order.status <> 'completed'
     OR v_order.approved_at IS NULL
     OR (
       v_order.provider = 'toss'
       AND v_order.payment_key IS NULL
     )
     OR (
       v_order.provider = 'kakaopay'
       AND NOT EXISTS (
         SELECT 1
           FROM public.payment_provider_transactions ppt
          WHERE ppt.payment_order_id = v_order.id
            AND ppt.provider = 'kakaopay'
            AND ppt.provider_transaction_id IS NOT NULL
            AND ppt.provider_approval_id IS NOT NULL
            AND ppt.provider_status = 'SUCCESS_PAYMENT'
            AND ppt.payment_method_type = 'MONEY'
       )
     ) THEN
    RETURN jsonb_build_object('allowed', false, 'reason_code', 'REFUND_COMPLETED_PAYMENT_REQUIRED');
  END IF;

  v_refundable_until := v_order.approved_at + interval '7 days';

  IF v_source.status <> 'active' THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason_code', 'REFUND_SOURCE_NOT_ACTIVE',
      'refundable_until', v_refundable_until
    );
  END IF;

  IF v_source.remaining_credits <> v_source.initial_credits THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason_code', 'REFUND_CREDITS_ALREADY_USED',
      'refundable_until', v_refundable_until
    );
  END IF;

  IF v_source.expires_at IS NOT NULL AND v_source.expires_at <= now() THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason_code', 'REFUND_SOURCE_EXPIRED',
      'refundable_until', v_refundable_until
    );
  END IF;

  IF now() > v_refundable_until THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason_code', 'REFUND_REQUEST_PERIOD_EXPIRED',
      'refundable_until', v_refundable_until
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'reason_code', null,
    'provider', v_order.provider,
    'refundable_until', v_refundable_until
  );
END;
$function$
